const business={name:'Burger e Pão Tianguá Hamburgueria',phone:'+5588999344206',order:'https://delivery.yooga.app/burger-e-pao?ref=e036441b-6466-4d0d-ba87-6366c005eedc',address:'Avenida Prefeito Jaques Nunes, 2350, vila salles, 12 - Rodoviaria, Tianguá - CE, 62320-001',rating:5,ratingCount:4,photos:{logo:'assets/logo.png',food:'assets/burger.webp'}};
document.querySelectorAll('[data-order]').forEach(a=>{a.href=business.order;a.target='_blank';a.rel='noopener noreferrer'});
document.querySelectorAll('[data-route]').forEach(a=>{a.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(business.name+' '+business.address);a.target='_blank';a.rel='noopener noreferrer'});
document.querySelectorAll('[data-phone]').forEach(a=>a.href='tel:'+business.phone);document.getElementById('year').textContent=new Date().getFullYear();
const toggle=document.querySelector('.menu-toggle'),nav=document.getElementById('navigation');function closeMenu(){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir menu')}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});
nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();toggle.focus()}});document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu()});
const paths={pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',table:'<path d="M3 10h18M5 10v11M19 10v11M7 3v7M17 3v7M3 5h8M13 5h8"/>',delivery:'<path d="M3 5h11v12H3zM14 9h4l3 4v4h-7"/><circle cx="7" cy="18" r="3"/><circle cx="18" cy="18" r="3"/>'};document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[el.dataset.icon]+'</svg>');
const active=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)nav.querySelectorAll('a[href^="#"]').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-15% 0px -60% 0px'});document.querySelectorAll('main section[id]').forEach(el=>active.observe(el));
const schema=document.createElement('script');schema.type='application/ld+json';schema.textContent=JSON.stringify({'@context':'https://schema.org','@type':'Restaurant',name:business.name,telephone:business.phone,hasMenu:business.order,address:{'@type':'PostalAddress',streetAddress:'Avenida Prefeito Jaques Nunes, 2350, vila salles, 12 - Rodoviaria',addressLocality:'Tianguá',addressRegion:'CE',postalCode:'62320-001',addressCountry:'BR'}});document.head.append(schema);
